const b = $json.body || $json;
const n = b.nuevos || {}; const c = b.cambios || {};
const texto = [
  '📣 Pidieron más cupo de la carta en video',
  `Empresa: ${b.empresa || b.company_id}`,
  `Qué pidió: ${b.pidio || '-'}`,
  `Quién: ${b.por || '-'}`,
  `Mes ${b.mes}: ${n.used ?? '?'} de ${n.limit ?? '?'} platos nuevos y ${c.used ?? '?'} de ${c.limit ?? '?'} cambios`,
  `Ficha en v2+: ${b.ficha_url || ''}`,
].join('\n');
return [{ json: { texto, asunto: `Cupo carta en video: ${b.empresa || b.company_id}` } }];
